//! Interpreter tests: the semantics a JIT will be diffed against.
//!
//! **No instruction word in this file was typed by hand.** Every sequence comes from
//! `tests/fixtures/programs.tsv`, generated by assembling real source with `llvm-mc`. The first
//! draft of this file contained encodings written from memory and five of them were wrong — which
//! is precisely the failure mode the fixture removes.
//!
//! The flag cases are deliberate. `C` on subtraction is not-borrow and `V` is signed overflow, not
//! the sign of the result; a conditional branch reading the wrong one fails only on inputs nobody
//! tested.

use std::collections::BTreeMap;

use vitrine::interp::{Machine, Trap, decode_bitmask};

fn programs() -> BTreeMap<String, Vec<u32>> {
    let raw = include_str!("fixtures/programs.tsv");
    let mut out = BTreeMap::new();
    for line in raw.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let mut fields = line.split('\t');
        let name = fields.next().expect("name").to_string();
        let words = fields
            .next()
            .expect("words")
            .split_whitespace()
            .map(|w| u32::from_str_radix(w.trim_start_matches("0x"), 16).expect("hex word"))
            .collect();
        out.insert(name, words);
    }
    out
}

fn load(name: &str) -> Machine {
    let words = programs()
        .remove(name)
        .unwrap_or_else(|| panic!("no fixture named {name}"));
    let mut m = Machine::new(0, 0x2000);
    m.load_code(0, &words);
    m.sp = 0x1800;
    m
}

fn run_to_exit(m: &mut Machine) -> u64 {
    match m.run(10_000) {
        Err(Trap::SupervisorCall { .. }) => m.x[0],
        other => panic!("expected the exit syscall, got {other:?}"),
    }
}

#[test]
fn subtraction_sets_carry_as_not_borrow() {
    let mut m = load("cmp_zero_vs_one");
    m.step().unwrap();
    m.step().unwrap();
    assert!(m.n, "0 - 1 is negative");
    assert!(!m.z);
    assert!(!m.c, "a borrow occurred, so C (not-borrow) is clear");
    assert!(!m.v);
}

#[test]
fn subtraction_without_borrow_sets_carry() {
    let mut m = load("cmp_five_vs_one");
    m.step().unwrap();
    m.step().unwrap();
    assert!(m.c, "no borrow, so C is set");
    assert!(!m.n);
    assert!(!m.z);
}

#[test]
fn equality_sets_z() {
    let mut m = load("cmp_five_vs_five");
    m.step().unwrap();
    m.step().unwrap();
    assert!(m.z);
    assert!(m.c);
    assert!(!m.n);
}

#[test]
fn signed_overflow_is_not_the_sign_of_the_result() {
    let mut m = load("adds_one_to_x2");
    m.x[2] = i64::MAX as u64;
    m.step().unwrap();
    assert_eq!(m.x[2], 1u64 << 63, "wrapped to the most negative value");
    assert!(m.n, "result is negative");
    assert!(m.v, "adding 1 to MAX overflows");
}

#[test]
fn a_w_register_write_zeroes_the_upper_half() {
    let mut m = load("add_w1_one");
    m.x[1] = 0xFFFF_FFFF_0000_0000;
    m.step().unwrap();
    assert_eq!(m.x[1], 1, "a 32-bit result must clear the top 32 bits");
}

#[test]
fn division_by_zero_yields_zero_and_does_not_trap() {
    let mut m = load("udiv_by_zero");
    assert_eq!(run_to_exit(&mut m), 0);
}

#[test]
fn signed_division_rounds_toward_zero() {
    let mut m = load("sdiv_x0");
    m.x[1] = (-100i64) as u64;
    m.x[2] = 7;
    // Truncation toward zero, and the raw register value — not an exit byte.
    assert_eq!(run_to_exit(&mut m), (-14i64) as u64);
}

#[test]
fn bitmask_immediates_match_the_architectural_definition() {
    // For a 64-bit operand the element size is 64, which requires immN = 1.
    // immr=0, imms=7  -> 0xFF   (the #0xFF in the fixture's `mov x1, #0xFF`)
    assert_eq!(decode_bitmask(true, true, 0, 7), 0xFF);
    // The #0xF0 in `and x0, x1, #0xF0` is encoded as immr=60, imms=3 — a rotate of 0xF by four,
    // which is what the assembler actually emits (verified by reading the fixture's fields, not by
    // guessing a nicer-looking pair).
    assert_eq!(decode_bitmask(true, true, 60, 3), 0xF0);
    // immr=4, imms=7 would be a *different* constant: 0xF at both ends of the word.
    assert_eq!(decode_bitmask(true, true, 4, 7), 0xF000_0000_0000_000F);
    // imms=0 is a run of ONE one, replicated: not an all-ones mask.
    assert_eq!(decode_bitmask(true, true, 0, 0), 1);
    // All ones takes imms=63 with a 64-bit element.
    assert_eq!(decode_bitmask(true, true, 0, 63), u64::MAX);
    // A 32-bit element pattern: N=0 is only valid with sf = 0, where imms=7 gives 0xFF.
    assert_eq!(decode_bitmask(false, false, 0, 7), 0xFF);
}

#[test]
fn and_immediate_produces_the_masked_value() {
    let mut m = load("and_immediate");
    m.step().unwrap();
    m.step().unwrap();
    assert_eq!(m.x[0], 0xF0);
}

#[test]
fn load_store_pre_and_post_index_write_the_base_back() {
    let mut m = load("pre_post_index");
    m.x[1] = 0xDEAD_BEEF;
    m.x[2] = 0x800;
    m.step().unwrap();
    assert_eq!(m.x[2], 0x808, "pre-index writes the base back");
    assert_eq!(m.read(0x808, 8).unwrap(), 0xDEAD_BEEF);
    m.step().unwrap();
    assert_eq!(m.x[3], 0xDEAD_BEEF);
    assert_eq!(
        m.x[2], 0x810,
        "post-index writes the base back after the access"
    );
}

#[test]
fn sign_extending_loads_extend_the_value() {
    let mut m = load("ldrsb");
    m.x[1] = 0x900;
    m.write(0x900, 1, 0x80).unwrap();
    m.step().unwrap();
    assert_eq!(
        m.x[0],
        (-128i64) as u64,
        "0x80 loads as -128 into an X register"
    );
}

#[test]
fn conditional_select_picks_the_right_arm() {
    let mut m = load("csel_eq");
    m.x[1] = 5;
    m.x[2] = 111;
    m.x[3] = 222;
    m.step().unwrap();
    m.step().unwrap();
    assert_eq!(m.x[0], 111, "equal: takes the first arm");
    m.x[1] = 6;
    m.pc = 0;
    m.step().unwrap();
    m.step().unwrap();
    assert_eq!(m.x[0], 222, "not equal: takes the second arm");
}

#[test]
fn a_whole_program_reaches_the_expected_result() {
    let mut m = load("mul_and_add");
    // 100 * 4 = 400, then 100 - 8 = 92, total 492 — the register value, not an exit status.
    assert_eq!(run_to_exit(&mut m), 492);
}

#[test]
fn an_undecoded_word_traps_with_its_address() {
    // A vector load, deliberately not implemented by the decoder.
    let mut m = Machine::new(0, 0x1000);
    m.load_code(0, &[0x3DC0_0000]);
    match m.step() {
        Err(Trap::Undecoded { pc, word }) => {
            assert_eq!(pc, 0);
            assert_eq!(word, 0x3DC0_0000);
        }
        other => panic!("expected Undecoded, got {other:?}"),
    }
}

#[test]
fn a_supervisor_call_is_reported_not_executed() {
    let mut m = Machine::new(0, 0x1000);
    m.load_code(0, &[0xD400_0001]);
    assert!(matches!(m.step(), Err(Trap::SupervisorCall { imm: 0 })));
}

#[test]
fn a_runaway_loop_hits_the_step_limit() {
    let mut m = Machine::new(0, 0x1000);
    m.load_code(0, &[0x1400_0000]); // b .
    assert!(matches!(m.run(50), Err(Trap::StepLimit { steps: 50 })));
}

#[test]
fn the_fixture_is_not_empty_and_every_program_has_words() {
    let p = programs();
    assert!(
        p.len() >= 10,
        "the fixture should cover every program the tests use"
    );
    for (name, words) in &p {
        assert!(!words.is_empty(), "{name} has no instructions");
    }
}

// ── the exclusive monitor: a lock that fails must SAY it failed ──────────────────────────────────
//
// ldxr/stxr encodings from `llvm-mc`. The failure path is the one that matters: a store-exclusive
// that cannot store still writes its status register, and a caller that ignores that has a lock
// which silently does nothing.

const LDXR_X0_X1: u32 = 0xC85F_7C20;
const STXR_W2_X3_X4: u32 = 0xC802_7C83;

#[test]
fn a_store_exclusive_after_a_matching_load_succeeds_and_stores() {
    let mut m = Machine::new(0x1000, 0x100);
    m.load_code(0x1000, &[LDXR_X0_X1, STXR_W2_X3_X4]);
    m.x[1] = 0x1040; // load address
    m.x[4] = 0x1040; // same address for the store
    m.x[3] = 0xAB; // value to store
    m.step().expect("ldxr executes");
    m.step().expect("stxr executes");

    assert_eq!(m.x[0], 0, "the load read zeroed memory");
    assert_eq!(m.x[2], 0, "status 0 = the store succeeded");
    assert_eq!(
        m.read(0x1040, 8).unwrap(),
        0xAB,
        "and the value is in memory"
    );
}

#[test]
fn a_store_exclusive_with_no_reservation_fails_and_writes_one() {
    let mut m = Machine::new(0x1000, 0x100);
    m.load_code(0x1000, &[STXR_W2_X3_X4]); // no preceding load
    m.x[4] = 0x1040;
    m.x[3] = 0xAB;
    m.step().expect("stxr executes");

    assert_eq!(m.x[2], 1, "status 1 = the store did not happen");
    assert_eq!(m.read(0x1040, 8).unwrap(), 0, "and memory is untouched");
}

#[test]
fn a_reservation_is_address_specific() {
    let mut m = Machine::new(0x1000, 0x100);
    m.load_code(0x1000, &[LDXR_X0_X1, STXR_W2_X3_X4]);
    m.x[1] = 0x1040; // armed here
    m.x[4] = 0x1048; // but stored here
    m.x[3] = 0xAB;
    m.step().expect("ldxr executes");
    m.step().expect("stxr executes");

    assert_eq!(
        m.x[2], 1,
        "a reservation for one address must not authorise another"
    );
    assert_eq!(m.read(0x1048, 8).unwrap(), 0, "and nothing was written");
}
